CREATE DATABASE IF NOT EXISTS labloop; USE labloop;
CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(50) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, role ENUM('STUDENT','LAB_ASSISTANT') NOT NULL, full_name VARCHAR(100) NOT NULL);
CREATE TABLE equipment (id INT AUTO_INCREMENT PRIMARY KEY, asset_code VARCHAR(30) NOT NULL UNIQUE, name VARCHAR(100) NOT NULL, category VARCHAR(60), status ENUM('AVAILABLE','BORROWED','MAINTENANCE') NOT NULL DEFAULT 'AVAILABLE', condition_state ENUM('GOOD','FAIR','DAMAGED') NOT NULL DEFAULT 'GOOD', purchase_date DATE, location VARCHAR(100), notes TEXT);
CREATE TABLE loans (id INT AUTO_INCREMENT PRIMARY KEY, equipment_id INT NOT NULL, student_id INT NOT NULL, borrowed_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, due_at DATETIME, returned_at DATETIME NULL, issued_condition ENUM('GOOD','FAIR','DAMAGED') NOT NULL, return_condition ENUM('GOOD','FAIR','DAMAGED') NULL, return_notes TEXT, FOREIGN KEY (equipment_id) REFERENCES equipment(id), FOREIGN KEY (student_id) REFERENCES users(id));
CREATE TABLE maintenance_records (id INT AUTO_INCREMENT PRIMARY KEY, equipment_id INT NOT NULL, assistant_id INT NOT NULL, record_type ENUM('INSPECTION','MAINTENANCE') NOT NULL, record_date DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, condition_before ENUM('GOOD','FAIR','DAMAGED'), condition_after ENUM('GOOD','FAIR','DAMAGED'), notes TEXT, FOREIGN KEY (equipment_id) REFERENCES equipment(id), FOREIGN KEY (assistant_id) REFERENCES users(id));
